// Uploads the built artifact to the release bucket.
const { spawnSync } = require("child_process");
const fs = require("fs");

const BUCKET = "releases-eu-prod";
const VERSION = require("./version.json").version;
const ARTIFACT = "dist/app.js";

function objectName(version) {
  return `app-${version}.js`;
}

function main() {
  const body = fs.readFileSync(ARTIFACT);
  const name = objectName(VERSION);
  const result = spawnSync(
    "aws",
    [
      "s3api",
      "put-object",
      "--bucket",
      BUCKET,
      "--key",
      name,
      "--body",
      ARTIFACT,
    ],
    { stdio: "inherit" },
  );

  if (result.error) {
    throw new Error(`failed to run aws s3api put-object: ${result.error.message}`);
  }
  if (result.status !== 0) {
    throw new Error(`aws s3api put-object exited with status ${result.status}`);
  }

  console.log(`uploaded ${name} (${body.length} bytes)`);
}

main();
